rewrite:
def recommend_pizza(toppings):
    if "Pepperoni" in toppings or "Veggies" in toppings:
        print("I recommend a Pizza with a potential choking hazard!")
    if "Pepperoni" in toppings or "Cheese" in toppings:
        print("I recommend a Pizza that may cause dairy intolerance!")

